-- HALO: apply migration 0029 in one paste.
-- Generated by scripts/build-apply-bundle.mjs from supabase/migrations; do not edit by hand.
-- Needs 0016, 0017 and 0026 applied first (0026 is not on production yet: apply it first). It reads 0023 only for a summary that names a task. It does not need 0024, 0025, 0027 or 0028.
-- One transaction: if any statement fails, nothing is changed (run `rollback;` if the
-- editor says the transaction is aborted), then send the error text. Safe to run twice.
-- Afterwards run verify-0029.sql and expect all_migrations_ok = true.

begin;

-- ===========================================================================
-- 0029_household_summaries.sql
-- ===========================================================================

-- HALO: saved household summaries, each an immutable snapshot of the records
-- a person selected, with one commit function that checks every selected
-- record at its exact revision and settles its own ledger row (B15 plan,
-- docs/backend/plans/b15-saved-summaries.md, Rulings S15-1 to S15-11).
--
-- Run once in the Supabase SQL editor, AFTER 0016 (home contexts), 0017 (the
-- ledger) and 0026 (the Homeguard workspace). It reads 0023's tasks only when
-- a summary names one, so 0023 is needed only for that. It does not need
-- 0024, 0025, 0027 or 0028 and may go before or after any of them. Safe to
-- re-run.
--
-- Locks: creates one new table and one index, which no other statement can be
-- waiting on. The foreign key to profiles takes a brief SHARE ROW EXCLUSIVE on
-- profiles as it is created, so a new anonymous sign-up could wait a moment.
-- It also adds two triggers to public.operations (sections 4 and 5), each
-- taking a brief SHARE ROW EXCLUSIVE on that table: every ledger claim and
-- settle waits for that moment. Nothing existing is read or rewritten.
--
-- WHAT THIS IS FOR. Homeguard's Summary prepares a household summary with
-- `summary.prepare`, lists saved ones with `summary.list` and reopens one with
-- `summary.read` (the frontend's runtime.ts:74-76). A saved summary is the
-- frozen report the server composed from the selected records, the selection
-- it was asked for, the omissions it disclosed and a manifest naming every
-- record it drew on at its revision. It is never re-derived on read and never
-- rewritten: section 1's trigger refuses every UPDATE (Ruling S15-1).
--
-- ONE COMMIT, ONE TRANSACTION (the 0026 pattern). The route reads the
-- selected records, composes the snapshot in JavaScript and then calls
-- public.commit_household_summary, which in one statement:
--
--   1. Locks the profile first (0024's lock order), FOR NO KEY UPDATE, so two
--      prepares of one household commit one after the other and step 4's
--      count cannot be overshot (another writer's KEY SHARE is not blocked),
--      then the caller's own ledger row, this household's, domain 'summary',
--      still 'pending'. Otherwise HALO_OPERATION_NOT_PENDING.
--   2. Checks the snapshot's home is the household's current home, held FOR
--      SHARE until the commit (Ruling S15-2). Otherwise HALO_HOME_CHANGED.
--   3. Checks every manifest record is this household's at exactly its
--      revision, each held FOR SHARE so no save can change it before the
--      commit (Ruling S15-5). Otherwise HALO_STALE_REVISION.
--   4. Keeps the household within 200 saved summaries (Ruling S15-9), or
--      HALO_LIMIT.
--   5. Inserts the summary and settles the ledger row 'succeeded' with the
--      summary id only, never report content (Ruling S15-11).
--   6. Returns the saved snapshot, read back in this transaction.
--
-- So a summary exists if and only if its operation is 'succeeded'. The reaper
-- in lib/operations.js settles an abandoned row 'failed' with a conditional
-- `update ... where status = 'pending'`, and step 1 locks the same row under
-- the same condition, so a reaped row never becomes 'succeeded'.
--
-- Errors the functions raise, for the routes to map. Each is SQLSTATE P0001
-- with exactly this message; DETAIL says more and never holds report content:
--   HALO_INVALID_INPUT          an argument or p_summary is malformed
--   HALO_OPERATION_NOT_PENDING  the ledger row is missing, settled, another
--                               household's or another domain's
--   HALO_HOME_CHANGED           the household's current home is not the snapshot's
--   HALO_STALE_REVISION         a selected record is not there at its revision
--   HALO_LIMIT                  the household already has 200 saved summaries
--   HALO_SUMMARY_IMMUTABLE      section 1: a saved summary may not be changed
--   HALO_OPERATION_SETTLED      section 4: a settled 'summary' row's status may
--                               not change
--
-- Degrades cleanly: until this is applied the B15 routes answer a
-- non-retryable 503 feature_unavailable (a prepare a 200 'failed' receipt
-- recorded nowhere), because a missing function is PGRST202 or 42883 and a
-- missing table PGRST205 or 42P01. Nothing else reads this table.
--
-- DELETION. profile_id references profiles ON DELETE CASCADE, so deleting the
-- account deletes every summary. A privacy clear all (0024) resets the profile
-- instead of deleting it, so section 5's trigger deletes the household's
-- summaries when that clear settles its own ledger row, inside the clear's
-- transaction (the 0026 pattern). Clear Journal keeps them.
--
-- Retention (Ruling S15-4, proposed): kept until the household clears all or
-- deletes the account. No purge job is defined here on purpose, and no period
-- is invented: summaries stay behind the `summaries` server flag, off by
-- default, until Vibhav confirms.
--
-- Privacy: the service role is the only reader. Row level security is on with
-- no policy at all and the default privileges are revoked, so not even the
-- owner can read their own summaries with their own session. No attachment
-- bytes, photo data or file metadata are ever written here (Ruling S15-8).

-- ---------------------------------------------------------------------------
-- 1. The table, and its immutability
-- ---------------------------------------------------------------------------

create table if not exists public.household_summaries (
  -- SummaryArchive.id: a server uuid, new for every prepare (Ruling S15-1).
  summary_id      uuid        primary key,
  -- The owner, from the verified session only.
  profile_id      uuid        not null references public.profiles (id) on delete cascade,
  -- The ledger row that created it, one summary per operation.
  operation_id    uuid        not null unique,
  -- SummaryArchive.revision: 1, since a summary is never rewritten.
  revision        integer     not null default 1,
  -- One of the four purposes the screen offers (Ruling S15-9).
  title           text        not null,
  -- The household's current home when it was prepared, frozen. No foreign
  -- key on purpose: a later change to home_contexts must not touch it.
  home_context_id uuid,
  -- The frozen HouseholdReport, the echoed SummarySelection, the manifest and
  -- the omissions, exactly as the client's validator accepts them.
  report          jsonb       not null,
  selection       jsonb       not null,
  manifest        jsonb       not null,
  omissions       jsonb       not null,
  created_at      timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'household_summaries_revision_check') then
    alter table public.household_summaries add constraint household_summaries_revision_check
      check (revision >= 1);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_summaries_title_check') then
    alter table public.household_summaries add constraint household_summaries_title_check
      check (char_length(title) between 1 and 200);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_summaries_shape_check') then
    alter table public.household_summaries add constraint household_summaries_shape_check
      check (jsonb_typeof(report) = 'object' and jsonb_typeof(selection) = 'object'
             and jsonb_typeof(manifest) = 'array' and jsonb_typeof(omissions) = 'array');
  end if;
  -- A backstop for Ruling S15-9's 2,000,000-byte snapshot, which the route
  -- checks first on the JSON it built. jsonb prints a space after every ':'
  -- and ',', so the same value is up to 1.5 times longer as text: the
  -- backstop sits above 3,000,000.
  if not exists (select 1 from pg_constraint where conname = 'household_summaries_size_check') then
    alter table public.household_summaries add constraint household_summaries_size_check
      check (octet_length(report::text) + octet_length(selection::text) + octet_length(manifest::text)
             + octet_length(omissions::text) <= 3200000);
  end if;
end $$;

-- A household's list: newest first, the id breaking a tie.
create index if not exists household_summaries_owner_created
  on public.household_summaries (profile_id, created_at desc, summary_id);

alter table public.household_summaries enable row level security;

-- No policy, deliberately: every read and write goes through a route handler
-- using the service role after it has verified the token. Supabase's default
-- privileges would otherwise grant anon and authenticated arwdDxtm on a new
-- public table, so revoking here is what actually closes that.
revoke all on table public.household_summaries from anon, authenticated;

-- A saved summary is immutable (Ruling S15-1): no column of a row may change,
-- by anyone. Deleting it (clear all, the account's cascade) is allowed.
create or replace function public.guard_household_summary_update()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  raise exception 'HALO_SUMMARY_IMMUTABLE' using errcode = 'P0001',
    detail = 'a saved household summary is never changed';
end;
$$;

revoke execute on function public.guard_household_summary_update() from public, anon, authenticated;

create or replace trigger household_summaries_immutable
  before update on public.household_summaries
  for each row
  execute function public.guard_household_summary_update();

-- ---------------------------------------------------------------------------
-- 2. Reads
-- ---------------------------------------------------------------------------
-- p_profile_id is trusted: only the service role may call these, and the
-- routes pass the verified session's user id. createdAt is printed in UTC
-- with milliseconds, the form JavaScript's toISOString gives, so the value a
-- prepare composed and the value a read returns are the same string.

create or replace function public.household_summary_json(s public.household_summaries)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_build_object(
    'id', s.summary_id,
    'revision', s.revision,
    'title', s.title,
    'createdAt', to_char(s.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'homeContextId', s.home_context_id,
    'report', s.report,
    'selection', s.selection,
    'manifest', s.manifest,
    'omissions', s.omissions
  );
$$;

revoke execute on function public.household_summary_json(public.household_summaries) from public, anon, authenticated;
grant execute on function public.household_summary_json(public.household_summaries) to service_role;

-- The household's archive list, newest first: {items: [archive], complete}.
-- complete is false only when more than p_limit summaries exist. One
-- statement, so not truncated by PostgREST's max_rows.
create or replace function public.read_household_summaries(p_profile_id uuid, p_limit integer)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
declare
  total int;
begin
  if p_profile_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id is required';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_limit must be 1 to 1000';
  end if;
  select count(*) into total from public.household_summaries s where s.profile_id = p_profile_id;
  return jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', l.summary_id,
               'revision', l.revision,
               'title', l.title,
               'createdAt', to_char(l.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
               'homeContextId', l.home_context_id
             ) order by l.created_at desc, l.summary_id)
        from (select s.summary_id, s.revision, s.title, s.created_at, s.home_context_id
                from public.household_summaries s
               where s.profile_id = p_profile_id
               order by s.created_at desc, s.summary_id
               limit p_limit) l), '[]'::jsonb),
    'complete', total <= p_limit
  );
end;
$$;

revoke execute on function public.read_household_summaries(uuid, integer) from public, anon, authenticated;
grant execute on function public.read_household_summaries(uuid, integer) to service_role;

-- One saved summary of this household, or null: another household's id is
-- exactly a missing one.
create or replace function public.read_household_summary(p_profile_id uuid, p_summary_id uuid)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_profile_id is null or p_summary_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id and p_summary_id are required';
  end if;
  return (select public.household_summary_json(s) from public.household_summaries s
           where s.profile_id = p_profile_id and s.summary_id = p_summary_id);
end;
$$;

revoke execute on function public.read_household_summary(uuid, uuid) from public, anon, authenticated;
grant execute on function public.read_household_summary(uuid, uuid) to service_role;

-- How many summaries the household has saved: the early limit answer, and the
-- route's proof before its ledger claim that 0029 is applied.
create or replace function public.household_summary_usage(p_profile_id uuid)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_profile_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id is required';
  end if;
  return jsonb_build_object('summaries',
    (select count(*) from public.household_summaries s where s.profile_id = p_profile_id));
end;
$$;

revoke execute on function public.household_summary_usage(uuid) from public, anon, authenticated;
grant execute on function public.household_summary_usage(uuid) to service_role;

-- ---------------------------------------------------------------------------
-- 3. commit_household_summary: the atomic save
-- ---------------------------------------------------------------------------
-- p_operation_id is the caller's own ledger row, already claimed by
-- runOperation. p_summary is the route's composed snapshot, exactly these
-- keys: id, title, createdAt, homeContextId, report, selection, manifest,
-- omissions. Manifest rows are {kind, id, revision, asOf}; kind 'tests',
-- 'maintenance' (the 'assets' collection), 'observations' or 'gardens' names
-- a workspace record, 'actions' one of 0023's tasks. Nothing is written for
-- any refusal.

create or replace function public.commit_household_summary(
  p_profile_id    uuid,
  p_operation_id  uuid,
  p_summary       jsonb
)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  summary_keys constant text[] := array['createdAt', 'homeContextId', 'id', 'manifest', 'omissions', 'report', 'selection', 'title'];
  workspace_kinds constant text[] := array['tests', 'maintenance', 'observations', 'gardens'];
  v_id          uuid;
  v_home        uuid;
  v_created     timestamptz;
  current_home  uuid;
  wanted        int;
  matched       int;
  saved         int;
  touched       int;
begin
  -- Arguments first: nothing is read or written for a malformed call.
  if p_profile_id is null or p_operation_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id and p_operation_id are required';
  end if;
  if p_summary is null or jsonb_typeof(p_summary) <> 'object'
     or (select array_agg(k order by k) from jsonb_object_keys(p_summary) k) is distinct from summary_keys then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_summary must have exactly the snapshot keys';
  end if;
  if jsonb_typeof(p_summary -> 'id') <> 'string' or jsonb_typeof(p_summary -> 'title') <> 'string'
     or jsonb_typeof(p_summary -> 'createdAt') <> 'string'
     or jsonb_typeof(p_summary -> 'homeContextId') not in ('string', 'null')
     or jsonb_typeof(p_summary -> 'report') <> 'object' or jsonb_typeof(p_summary -> 'selection') <> 'object'
     or jsonb_typeof(p_summary -> 'manifest') <> 'array' or jsonb_typeof(p_summary -> 'omissions') <> 'array' then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_summary has a value of the wrong type';
  end if;
  begin
    v_id := (p_summary ->> 'id')::uuid;
    v_home := (p_summary ->> 'homeContextId')::uuid;
    v_created := (p_summary ->> 'createdAt')::timestamptz;
  exception when others then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'id, homeContextId or createdAt is malformed';
  end;
  if abs(extract(epoch from (clock_timestamp() - v_created))) > 600 then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'createdAt must be the time of this prepare';
  end if;
  if exists (select 1 from jsonb_array_elements(p_summary -> 'manifest') e
              where jsonb_typeof(e) <> 'object'
                 or jsonb_typeof(e -> 'kind') <> 'string' or jsonb_typeof(e -> 'id') <> 'string'
                 or jsonb_typeof(e -> 'revision') <> 'number'
                 or (e ->> 'kind') <> all (workspace_kinds || array['actions'])) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'manifest rows must name a record kind, id and revision';
  end if;
  if exists (select 1 from jsonb_array_elements(p_summary -> 'manifest') e
              where (e ->> 'revision')::numeric < 1 or (e ->> 'revision')::numeric <> trunc((e ->> 'revision')::numeric)
                 or (e ->> 'revision')::numeric >= 2147483647)
     or exists (select 1 from jsonb_array_elements(p_summary -> 'manifest') e
                 group by e ->> 'kind', e ->> 'id' having count(*) > 1) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'manifest revisions must be whole numbers from 1, each record once';
  end if;

  -- 1. The profile (serialising this household's summary commits), then this operation's own ledger row.
  perform 1 from public.profiles p where p.id = p_profile_id for no key update;
  perform 1 from public.operations o
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'summary' and o.status = 'pending'
     for update;
  if not found then
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;

  -- 2. The current home, held until the commit (Ruling S15-2).
  select c.id into current_home from public.home_contexts c
   where c.profile_id = p_profile_id and c.effective_to is null
   for share;
  if current_home is distinct from v_home then
    raise exception 'HALO_HOME_CHANGED' using errcode = 'P0001', detail = 'the current home is not the snapshot''s';
  end if;

  -- 3. Every selected workspace record at exactly its revision, held FOR
  --    SHARE: an update of one waits for this commit (Ruling S15-5).
  select count(*) into wanted from jsonb_array_elements(p_summary -> 'manifest') e
   where (e ->> 'kind') = any (workspace_kinds);
  select count(*) into matched from (
    select 1 from public.household_workspace_records r
      join jsonb_array_elements(p_summary -> 'manifest') e
        on r.collection = case e ->> 'kind' when 'maintenance' then 'assets' else e ->> 'kind' end
       and r.record_id = e ->> 'id'
       and r.revision = (e ->> 'revision')::int
     where r.profile_id = p_profile_id and (e ->> 'kind') = any (workspace_kinds)
       for share of r
  ) locked;
  if matched <> wanted then
    raise exception 'HALO_STALE_REVISION' using errcode = 'P0001', detail = 'a selected record is not there at its revision';
  end if;
  --    And every selected task (0023), only when the summary names one, so a
  --    database without 0023 can still save every other summary.
  if exists (select 1 from jsonb_array_elements(p_summary -> 'manifest') e where (e ->> 'kind') = 'actions') then
    select count(*) into wanted from jsonb_array_elements(p_summary -> 'manifest') e where (e ->> 'kind') = 'actions';
    select count(*) into matched from (
      select 1 from public.household_actions a
        join jsonb_array_elements(p_summary -> 'manifest') e
          on a.id::text = e ->> 'id' and a.revision = (e ->> 'revision')::int
       where a.profile_id = p_profile_id and (e ->> 'kind') = 'actions'
         for share of a
    ) locked;
    if matched <> wanted then
      raise exception 'HALO_STALE_REVISION' using errcode = 'P0001', detail = 'a selected task is not there at its revision';
    end if;
  end if;

  -- 4. The household's limit (Ruling S15-9).
  select count(*) into saved from public.household_summaries s where s.profile_id = p_profile_id;
  if saved >= 200 then
    raise exception 'HALO_LIMIT' using errcode = 'P0001', detail = 'the household already has 200 saved summaries';
  end if;

  -- 5. Insert, then settle this operation's own row with the id only.
  insert into public.household_summaries
    (summary_id, profile_id, operation_id, revision, title, home_context_id, report, selection, manifest, omissions, created_at)
  values
    (v_id, p_profile_id, p_operation_id, 1, p_summary ->> 'title', v_home, p_summary -> 'report',
     p_summary -> 'selection', p_summary -> 'manifest', p_summary -> 'omissions', v_created);

  update public.operations o
     set status = 'succeeded',
         result = jsonb_build_object('status', 'succeeded', 'summaryId', v_id, 'unresolvedOperations', '[]'::jsonb),
         updated_at = now()
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'summary' and o.status = 'pending';
  get diagnostics touched = row_count;
  if touched <> 1 then
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;

  -- 6. The saved snapshot, read back in this transaction.
  return public.read_household_summary(p_profile_id, v_id);
end;
$$;

revoke execute on function public.commit_household_summary(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.commit_household_summary(uuid, uuid, jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 4. A settled 'summary' operation keeps its status (the 0026 guard)
-- ---------------------------------------------------------------------------
-- runOperation settles by operation id alone and settles 'failed' whenever
-- its execute throws. If the commit function committed and its response was
-- lost, that settle would turn a 'succeeded' row whose summary was saved into
-- 'failed'. In the 'summary' domain only, a row that has left 'pending' may
-- not change its status: the settle fails, lib/operations.js logs it rather
-- than throwing, and the row keeps telling the truth.

create or replace function public.guard_settled_summary_operation()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  raise exception 'HALO_OPERATION_SETTLED' using errcode = 'P0001',
    detail = format('operation %s is already %s', old.operation_id, old.status);
end;
$$;

revoke execute on function public.guard_settled_summary_operation() from public, anon, authenticated;

create or replace trigger operations_summary_settled_guard
  before update on public.operations
  for each row
  when (old.domain = 'summary' and old.status <> 'pending' and new.status is distinct from old.status)
  execute function public.guard_settled_summary_operation();

-- ---------------------------------------------------------------------------
-- 5. Clear all removes the summaries too (the 0026 pattern)
-- ---------------------------------------------------------------------------
-- 0024's clear_household_records settles its own 'privacy.clear.all' row
-- from 'pending' to 'succeeded' as its last write, in its own transaction.
-- This trigger deletes the same household's summaries at that moment, so
-- they go with the clear or not at all, without changing 0024. A clear that
-- refuses raises before it settles, so it deletes nothing here. Clear Journal
-- ('privacy.clear.journal') does not touch summaries.

create or replace function public.clear_summaries_with_privacy_clear()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  delete from public.household_summaries s where s.profile_id = new.profile_id;
  return null;
end;
$$;

revoke execute on function public.clear_summaries_with_privacy_clear() from public, anon, authenticated;

create or replace trigger operations_privacy_clear_summaries
  after update on public.operations
  for each row
  when (new.domain = 'privacy' and new.kind = 'privacy.clear.all' and old.status = 'pending'
        and new.status = 'succeeded' and new.profile_id is not null)
  execute function public.clear_summaries_with_privacy_clear();

-- What a clear all would remove, for the privacy review's counts
-- (lib/privacyStore.js merges it into privacy_counts' answer).
create or replace function public.summary_privacy_counts(p_profile_id uuid)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_profile_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id is required';
  end if;
  return jsonb_build_object('household_summaries',
    (select count(*) from public.household_summaries s where s.profile_id = p_profile_id));
end;
$$;

revoke execute on function public.summary_privacy_counts(uuid) from public, anon, authenticated;
grant execute on function public.summary_privacy_counts(uuid) to service_role;

-- ---------------------------------------------------------------------------
-- Verification (read only). Expect one row, all seven columns true.
-- ---------------------------------------------------------------------------
--   select
--     (select relrowsecurity from pg_class where oid = 'public.household_summaries'::regclass) as rls_on,
--     (select count(*) from pg_policies
--       where schemaname = 'public' and tablename = 'household_summaries') = 0
--       as no_policies,
--     not exists (
--       select 1 from unnest(array['anon', 'authenticated']) as r
--        where has_any_column_privilege(r, 'public.household_summaries', 'SELECT')
